        self.items = items
        self.onDragStart = (element, rect) -> ()
        self.onDrop = (element, rect) -> ()
        self.onDragOver = DragOver<FeedView>(DragOver<FeedView>.extend(allowedDragTypes: [. move,. copy,. link]))
